from datetime import datetime, timezone
class TelemetryGenerator:
    def __init__(self, organization_id): self.organization_id = organization_id
    def event(self, source, hostname, event_type, severity="info", user="demo-user", **data): return {"organization_id": self.organization_id, "timestamp": datetime.now(timezone.utc).isoformat(), "source": source, "hostname": hostname, "user": user, "event_type": event_type, "severity": severity, "raw_data": data}
    def baseline(self): return [self.event("windows", "FIN-WIN-001", "successful_authentication", user="employee"), self.event("linux", "FIN-LINUX-001", "ssh_login", user="ops"), self.event("cloud", "AWS-PROD-001", "iam_activity", user="service-account"), self.event("firewall", "FIREWALL-001", "inbound_connection", source_ip="198.51.100.20")]
    def scenario(self, name):
        definitions = {"credential_attack": [("windows", "FIN-WIN-001", "failed_authentication", "high", {"message": "password spraying brute force"}), ("windows", "FIN-WIN-001", "successful_authentication", "high", {"message": "valid accounts suspicious remote access"}), ("firewall", "FIREWALL-001", "suspicious_ip_communication", "high", {"external_ip": "203.0.113.50"})], "malware_execution": [("windows", "FIN-WIN-002", "powershell_execution", "high", {"message": "powershell -enc suspicious script"}), ("windows", "FIN-WIN-002", "process_creation", "high", {"message": "process anomaly ioc"})], "ransomware_campaign": [("linux", "FIN-LINUX-001", "privilege_escalation", "critical", {"message": "sudo root"}), ("windows", "FIN-WIN-001", "encryption_activity", "critical", {"message": "data encrypted for impact"}), ("windows", "FIN-WIN-001", "recovery_deletion", "critical", {"message": "inhibit system recovery"})], "insider_threat": [("cloud", "AWS-PROD-001", "cloud_storage_access", "high", {"message": "data from cloud storage large download"}), ("firewall", "FIREWALL-001", "external_transfer", "high", {"message": "exfiltration over web service"})]}
        return [self.event(source, host, event_type, severity, **data) for source, host, event_type, severity, data in definitions.get(name, [])]
